8	
9	import Foundation
10	import MatrixRustSDK
11	import OrderedCollections
12	
13	enum RoomScreenViewModelAction: Equatable {
14	    case focusEvent(eventID: String)
15	    case displayThread(threadRootEventID: String, focussedEventID: String)
16	    case displayPinnedEventsTimeline
17	    case displayRoomDetails
18	    case displayCall
19	    case removeComposerFocus
20	    case displayKnockRequests
21	    case displayRoom(roomID: String, via: [String])
22	    case displayMessageForwarding(MessageForwardingItem)
23	}
24	
25	enum RoomScreenViewAction {
26	    case tappedPinnedEventsBanner
27	    case viewAllPins
28	    case displayRoomDetails
29	    case displayCall
30	    case footerViewAction(RoomScreenFooterViewAction)
31	    case acceptKnock(eventID: String)
32	    case dismissKnockRequests
33	    case viewKnockRequests
34	    case displaySuccessorRoom
35	}
36	
37	struct RoomScreenViewState: BindableState {
38	    var roomTitle = ""
39	    var roomAvatar: RoomAvatar
40	    var dmRecipientVerificationState: UserIdentityVerificationState?
41	    
42	    var lastScrollDirection: ScrollDirection?
43	    // This is used to control the banner
44	    var pinnedEventsBannerState: PinnedEventsBannerState = .loading(numbersOfEvents: 0)
45	    var shouldShowPinnedEventsBanner: Bool {
46	        !pinnedEventsBannerState.isEmpty && lastScrollDirection != .top
47	    }
48	    
49	    var canSendMessage = true
50	    
51	    /// Whether or not starting a call is supported.
52	    var isCallingEnabled = true
53	    /// Whether or not the user is allowed to join calls in this room.
54	    var canJoinCall = false
55	    /// Whether or not this room currently has a call in progress.
56	    var hasOngoingCall: Bool
57	    /// Whether or not the user is already part of a call in another room.
58	    var isParticipatingInOngoingCall = false
59	    var shouldShowCallButton: Bool {
60	        isCallingEnabled && !isParticipatingInOngoingCall // Hide the join call button when already in the call
61	    }
62	    
63	    var isKnockingEnabled = false
64	    var isKnockableRoom = false
65	    var canAcceptKnocks = false
66	    var canDeclineKnocks = false
67	    var canBan = false
68	    var unseenKnockRequests: [KnockRequestInfo] = []
69	    var handledEventIDs: Set<String> = []
70	    
71	    var hasSuccessor: Bool
72	    
73	    var displayedKnockRequests: [KnockRequestInfo] {
74	        unseenKnockRequests.filter { !handledEventIDs.contains($0.eventID) }
75	    }
76	    
77	    var shouldSeeKnockRequests: Bool {
78	        isKnockingEnabled &&
79	            isKnockableRoom &&
80	            !displayedKnockRequests.isEmpty &&
81	            (canAcceptKnocks || canDeclineKnocks || canBan)
82	    }
83	    
84	    /// If `enableKeyShareOnInvite` is set, determines the current history sharing state.
85	    var roomHistorySharingState: RoomHistorySharingState?
86	    
87	    var footerDetails: RoomScreenFooterViewDetails?
88	    
89	    var bindings = RoomScreenViewStateBindings()
90	}
91	
92	struct RoomScreenViewStateBindings {
93	    /// The view model used to present a QuickLook media preview.
94	    var mediaPreviewViewModel: TimelineMediaPreviewViewModel?
95	    var alertInfo: AlertInfo<RoomScreenAlertType>?
96	}
97	
98	enum RoomScreenAlertType {
99	    case unknown
100	}
101	
102	enum RoomScreenFooterViewAction {
103	    case resolvePinViolation(userID: String)
104	    case resolveVerificationViolation(userID: String)
105	}
106	
107	enum RoomScreenFooterViewDetails {
108	    case pinViolation(member: RoomMemberProxyProtocol, learnMoreURL: URL)
109	    case verificationViolation(member: RoomMemberProxyProtocol, learnMoreURL: URL)
110	}
111	
112	@MainActor
113	enum PinnedEventsBannerState: Equatable {
114	    case loading(numbersOfEvents: Int)
115	    case loaded(state: PinnedEventsState)
116	    
117	    var isEmpty: Bool {
118	        switch self {
119	        case .loaded(let state):
120	            return state.pinnedEventContents.isEmpty
121	        case .loading(let numberOfEvents):
122	            return numberOfEvents == 0
123	        }
124	    }
125	    
126	    var isLoading: Bool {
127	        switch self {
128	        case .loading:
129	            return true
130	        default:
131	            return false
132	        }
133	    }
134	    
135	    var selectedPinnedEventID: String? {
136	        switch self {
137	        case .loaded(let state):
138	            return state.selectedPinnedEventID
139	        default:
140	            return nil
141	        }
142	    }
143	    
144	    var count: Int {
145	        switch self {
146	        case .loaded(let state):
147	            return state.pinnedEventContents.count
148	        case .loading(let numberOfEvents):
149	            return numberOfEvents
150	        }
151	    }
152	    
153	    var selectedPinnedIndex: Int {
154	        switch self {
155	        case .loaded(let state):
156	            return state.selectedPinnedIndex
157	        case .loading(let numbersOfEvents):
158	            // We always want the index to be the last one when loading, since is the default one.
159	            return numbersOfEvents - 1
160	        }
161	    }
162	    
163	    var displayedMessage: AttributedString {
164	        switch self {
165	        case .loading:
166	            return AttributedString(L10n.screenRoomPinnedBannerLoadingDescription)
167	        case .loaded(let state):
168	            return state.selectedPinnedContent
169	        }
170	    }
171	    
172	    var bannerIndicatorDescription: AttributedString {
173	        let index = selectedPinnedIndex + 1
174	        let boldPlaceholder = "{bold}"
175	        var finalString = AttributedString(L10n.screenRoomPinnedBannerIndicatorDescription(boldPlaceholder))
176	        var boldString = AttributedString(L10n.screenRoomPinnedBannerIndicator(index, count))
177	        boldString.bold()
178	        finalString.replace(boldPlaceholder, with: boldString)
179	        return finalString
180	    }
181	    
182	    mutating func previousPin() {
183	        switch self {
184	        case .loaded(var state):
185	            state.previousPin()
186	            self = .loaded(state: state)
187	        default:
188	            break
189	        }
190	    }
191	    
192	    mutating func setPinnedEventContents(_ pinnedEventContents: OrderedDictionary<String, AttributedString>) {
193	        switch self {
194	        case .loading:
195	            // The default selected event should always be the last one.
196	            self = .loaded(state: .init(pinnedEventContents: pinnedEventContents, selectedPinnedEventID: pinnedEventContents.keys.last))
197	        case .loaded(var state):
198	            state.pinnedEventContents = pinnedEventContents
199	            self = .loaded(state: state)
200	        }
201	    }
202	    
203	    /// Note that if we are setting this value, this is definitely sent from the pinned events timeline
204	    /// so we can assume that the pinned events timeline is already loaded and we only need to set the
205	    /// selection for the loaded state
206	    mutating func setSelectedPinnedEventID(_ eventID: String) {
207	        switch self {
208	        case .loaded(var state):
209	            state.selectedPinnedEventID = eventID
210	            self = .loaded(state: state)
211	        case .loading:
212	            break
213	        }
214	    }
215	}
216	
217	@MainActor
218	struct PinnedEventsState: Equatable {
219	    var pinnedEventContents: OrderedDictionary<String, AttributedString> = [:] {
220	        didSet {
221	            if selectedPinnedEventID == nil, !pinnedEventContents.keys.isEmpty {
222	                // The default selected event should always be the last one.
223	                selectedPinnedEventID = pinnedEventContents.keys.last
224	            } else if pinnedEventContents.isEmpty {
225	                selectedPinnedEventID = nil
226	            } else if let selectedPinnedEventID, !pinnedEventContents.keys.set.contains(selectedPinnedEventID) {
227	                self.selectedPinnedEventID = pinnedEventContents.keys.last
228	            }
229	        }
230	    }
231	    
232	    var selectedPinnedEventID: String?
233	    
234	    var selectedPinnedIndex: Int {
235	        let defaultValue = pinnedEventContents.isEmpty ? 0 : pinnedEventContents.count - 1
236	        guard let selectedPinnedEventID else {
237	            return defaultValue
238	        }
239	        return pinnedEventContents.keys.firstIndex(of: selectedPinnedEventID) ?? defaultValue
240	    }
241	    
242	    var selectedPinnedContent: AttributedString {
243	        var content = AttributedString(" ")
244	        if let selectedPinnedEventID,
245	           let pinnedEventContent = pinnedEventContents[selectedPinnedEventID] {
246	            content = pinnedEventContent
247	        }
248	        content.font = .compound.bodyMD
249	        content.link = nil
250	        return content
251	    }
252	    
253	    mutating func previousPin() {
254	        guard !pinnedEventContents.isEmpty else {
255	            return
256	        }
257	        let currentIndex = selectedPinnedIndex
258	        let nextIndex = currentIndex - 1
259	        if nextIndex == -1 {
260	            selectedPinnedEventID = pinnedEventContents.keys.last
261	        } else {
262	            selectedPinnedEventID = pinnedEventContents.keys[nextIndex % pinnedEventContents.count]
263	        }
264	    }
265	}
